{
  "name": "cinescope",
  "version": "0.0.0",
  "license": "MIT",
  "private": true,
  "packageManager": "pnpm@11.1.0",
  "engines": {
    "node": ">=26.5.0",
    "pnpm": ">=11.1.0"
  },
  "scripts": {
    "api": "json-server --watch db.json --port 3000",
    "lint": "nx run-many -t lint",
    "format": "prettier --write ."
  },
  "devDependencies": {
    "@angular/build": "~22.0.4",
    "@angular/cli": "~22.0.4",
    "@angular/compiler-cli": "~22.0.4",
    "@eslint/js": "^9.39.5",
    "@nx/angular": "23.1.1",
    "@nx/eslint": "23.1.1",
    "@nx/eslint-plugin": "23.1.1",
    "@nx/web": "23.1.1",
    "angular-eslint": "^22.0.0",
    "eslint": "^9.39.5",
    "jsdom": "^27.1.0",
    "json-server": "0.17.4",
    "nx": "23.1.1",
    "prettier": "^3.8.1",
    "sass": "^1.97.2",
    "tslib": "^2.3.0",
    "typescript": "~6.0.3",
    "typescript-eslint": "^8.69.0",
    "vitest": "^4.0.8"
  },
  "dependencies": {
    "@angular/cdk": "~22.0.7",
    "@angular/common": "~22.0.4",
    "@angular/compiler": "~22.0.4",
    "@angular/core": "~22.0.4",
    "@angular/forms": "~22.0.4",
    "@angular/material": "~22.0.7",
    "@angular/platform-browser": "~22.0.4",
    "@angular/router": "~22.0.4",
    "rxjs": "~7.8.0"
  }
}
{
  "name": "cinescope",
  "$schema": "../../node_modules/nx/schemas/project-schema.json",
  "projectType": "application",
  "prefix": "app",
  "sourceRoot": "apps/cinescope/src",
  "tags": [],
  "targets": {
    "build": {
      "executor": "@angular/build:application",
      "outputs": [
        "{options.outputPath}"
      ],
      "defaultConfiguration": "production",
      "options": {
        "outputPath": "dist/apps/cinescope",
        "browser": "apps/cinescope/src/main.ts",
        "tsConfig": "apps/cinescope/tsconfig.app.json",
        "inlineStyleLanguage": "scss",
        "assets": [
          {
            "glob": "**/*",
            "input": "apps/cinescope/public"
          }
        ],
        "styles": [
          "apps/cinescope/src/styles.scss"
        ]
      },
      "configurations": {
        "production": {
          "budgets": [
            {
              "type": "initial",
              "maximumWarning": "500kb",
              "maximumError": "1mb"
            }
          ],
          "outputHashing": "all"
        },
        "development": {
          "optimization": false,
          "extractLicenses": false,
          "sourceMap": true
        }
      }
    },
    "serve": {
      "continuous": true,
      "executor": "@angular/build:dev-server",
      "defaultConfiguration": "development",
      "options": {
        "port": 4200
      },
      "configurations": {
        "production": {
          "buildTarget": "cinescope:build:production"
        },
        "development": {
          "buildTarget": "cinescope:build:development"
        }
      }
    },
    "lint": {
      "executor": "@nx/eslint:lint"
    },
    "test": {
      "executor": "@angular/build:unit-test",
      "options": {
        "watch": false
      }
    },
    "serve-static": {
      "continuous": true,
      "executor": "@nx/web:file-server",
      "options": {
        "buildTarget": "cinescope:build",
        "port": 4200,
        "staticFilePath": "dist/apps/cinescope/browser",
        "spa": true
      }
    }
  }
}
