18	export type AuditoriumItem = SeatItem | CouchItem;
19	
20	/** One row of the auditorium: the three blocks between the two aisles, left to right. */
21	export interface AuditoriumRow {
22	  number: number;
23	  blocks: AuditoriumItem[][];
24	}
25	
26	const ROW_COUNT = 15;
27	const COUCH_ROW = 15;
28	/** Rows 1 to 10 have no seats in columns 1 to 4: the entrance. */
29	const ENTRANCE_LAST_ROW = 10;
30	const ACCESSIBLE_ROW = 1;
31	const ACCESSIBLE_FIRST_COLUMN = 10;
32	const ACCESSIBLE_LAST_COLUMN = 15;
33	
34	export function seatIdentifier(row: number, column: number): string {
35	  return `R${row}C${column}`;
36	}
37	
38	/** Builds the auditorium: rows 1 to 15, each split into blocks of columns 1–4, 5–20 and 21–24. */
39	export function buildAuditorium(occupiedSeats: ReadonlySet<string>): AuditoriumRow[] {
40	  return Array.from({ length: ROW_COUNT }, (_, index) => {
41	    const number = index + 1;
42	    const left = number <= ENTRANCE_LAST_ROW ? [] : itemsFor(number, 1, 4, occupiedSeats);
43	    return {
44	      number,
45	      blocks: [left, itemsFor(number, 5, 20, occupiedSeats), itemsFor(number, 21, 24, occupiedSeats)],
46	    };
47	  });
48	}
49	
50	function itemsFor(row: number, firstColumn: number, lastColumn: number, occupied: ReadonlySet<string>): AuditoriumItem[] {
51	  const items: AuditoriumItem[] = [];
52	  if (row === COUCH_ROW) {
53	    for (let start = firstColumn; start <= lastColumn; start += 2) {
54	      const end = start + 1;
55	      const isOccupied = occupied.has(seatIdentifier(row, start)) || occupied.has(seatIdentifier(row, end));
56	      items.push({ kind: 'couch', row, start, end, state: isOccupied ? 'unavailable' : 'available' });
57	    }
58	    return items;
59	  }
60	  for (let column = firstColumn; column <= lastColumn; column++) {
61	    items.push({ kind: 'seat', row, column, state: seatState(row, column, occupied) });
62	  }
63	  return items;
64	}
65	
66	function seatState(row: number, column: number, occupied: ReadonlySet<string>): SeatState {
67	  if (occupied.has(seatIdentifier(row, column))) {
68	    return 'unavailable';
69	  }
70	  const isAccessible =
71	    row === ACCESSIBLE_ROW && column >= ACCESSIBLE_FIRST_COLUMN && column <= ACCESSIBLE_LAST_COLUMN;
72	  return isAccessible ? 'accessible' : 'available';
73	}
