.couch {
  height: var(--seat-size);
  margin: 0;
  padding: 0;
  border: 0;
  border-radius: 6px 6px 4px 4px;
  color: #ffffff;
  font: inherit;
  font-size: 0.75rem;
  line-height: 1;
  cursor: pointer;

  &:disabled {
    cursor: not-allowed;
  }
}

.seat {
  width: var(--seat-size);
}

// A couch covers two columns, so it is two seat widths plus the gap between them.
.couch {
  width: calc(2 * var(--seat-size) + var(--seat-gap));
  border-radius: 12px 12px 4px 4px;
}

// Colours are fixed per state; hover and focus leave the background unchanged.
@each $state, $colour in $state-colours {
  .seat[data-state='#{$state}'],
  .couch[data-state='#{$state}'],
  .legend-item[data-state='#{$state}'] .swatch {
    background-color: $colour;
  }
}

.seat[data-state='selected'],
.couch[data-state='selected'] {
  color: #212121;
}

.legend {
  display: flex;
  flex-wrap: wrap;
  justify-content: center;
  gap: 24px;
}

.legend-item {
  display: inline-flex;
  align-items: center;
  gap: 8px;
}

.swatch {
  width: 16px;
  height: 16px;
  border-radius: 4px;
}

.selected-seats {
  display: flex;
  flex-direction: column;
  gap: 4px;

  p {
    margin: 0;
  }
}

.actions {
  display: flex;
  gap: 16px;
}
