    </div>
  </div>

  <div class="actions">
    <button mat-stroked-button type="button" data-testid="checkout-back-button" (click)="onBack()">Back</button>
    <button mat-flat-button type="button" data-testid="pay-button" [disabled]="submitting()" (click)="pay()">
      @if (submitting()) {
        Processing…
      } @else {
