    89	    this.form.valueChanges
    90	      .pipe(takeUntilDestroyed())
    91	      .subscribe(() => this.bookings.setCheckout(this.form.getRawValue()));
    92	
    93	    // The confirmation is compared with the email as typed, so it is re-checked whenever the email changes.
    94	    this.form.controls.email.valueChanges
    95	      .pipe(takeUntilDestroyed())
    96	      .subscribe(() => this.form.controls.confirmEmail.updateValueAndValidity());
    97	  }
    98	
    99	  /** The message of a field's failing rule, or an empty string when the field is valid. */
   100	  protected messageOf(field: CheckoutField): string {
   101	    const errors = this.form.controls[field].errors ?? {};
   102	    const key = Object.keys(MESSAGES[field]).find((rule) => rule in errors);
   103	    return key === undefined ? '' : MESSAGES[field][key];
   104	  }
   105	
   106	  protected onTermsToggled(): void {
   107	    this.form.controls.terms.markAsTouched();
   108	  }
   109	
   110	  protected onBack(): void {
   111	    void this.router.navigate(['/screenings', this.screeningId(), 'summary']);
   112	  }
   113	
   114	  protected pay(): void {
   115	    this.form.markAllAsTouched();
   116	    if (this.form.invalid) {
   117	      this.toaster.show('The form contains errors');
   118	      return;
   119	    }
   120	
   121	    const booking = this.bookings.booking();
   122	    if (booking === null) {
   123	      void this.router.navigate(['/']);
   124	      return;
   125	    }
   126	
   127	    const values = this.form.getRawValue();
   128	    this.submitting.set(true);
   129	    this.api
   130	      .createReservation({
   131	        screeningId: booking.screeningId,
   132	        seats: ticketsFor(booking.seats).flatMap(identifiersOfTicket),
   133	        customer: {
   134	          firstName: values.firstName,
   135	          lastName: values.lastName,
   136	          email: values.email,
   137	          phone: values.phone,
   138	        },
   139	        totalPrice: totalOf(booking.seats),
   140	      })
   141	      .subscribe({
   142	        next: () => {
   143	          this.submitting.set(false);
   144	          this.bookings.markPaid(values.email);
   145	          void this.router.navigate(['/confirmation']);
   146	        },
   147	        error: () => {
   148	          this.submitting.set(false);
   149	          this.toaster.show('Payment failed. Please try again.');
   150	        },
   151	      });
   152	  }
   153	}
